window.PIATTAFORMA_SEED_COMPITI = window.PIATTAFORMA_SEED_COMPITI.concat([{"class_id": "1d", "title": "Il diario dei miei dati", "description": "Per un giorno annota almeno 10 dati che produci o che i tuoi dispositivi raccolgono e organizzali in una tabella di Calc, indicando la fase del ciclo input-elaborazione-output. Trasforma 3 dati in informazioni utili e scrivi una breve riflessione. Consegna il file diario-dati-cognome.ods.", "due_date": null, "planned_due": "2026-10-30", "topic": "La tecnologia dell'informazione", "pdf_url": "contenuti/compiti/tecnologia-informazione.pdf"}, {"class_id": "1d", "title": "La mia palette in esadecimale", "description": "Scegli un tema che ti piace e 5 colori che lo rappresentano, trova il loro codice #RRGGBB e converti a mano in decimale le tre luci e in binario il rosso. Verifica i calcoli con le funzioni di Calc e colora le celle. Consegna il file palette-cognome.ods.", "due_date": null, "planned_due": "2026-11-04", "topic": "I sistemi di numerazione binario, ottale ed esadecimale", "pdf_url": "contenuti/compiti/sistemi-di-numerazione.pdf"}, {"class_id": "1d", "title": "Le regole del gioco in logica", "description": "Scegli un gioco o uno sport, scrivi 4 proposizioni semplici e 3 regole che le combinano con AND, OR e NOT. Costruisci in Calc la tabella di verità di una regola con 3 proposizioni e spiega le righe vere. Consegna il file logica-cognome.ods.", "due_date": null, "planned_due": "2026-11-06", "topic": "La logica", "pdf_url": "contenuti/compiti/la-logica.pdf"}, {"class_id": "1d", "title": "Detective del sistema operativo", "description": "Compila la carta d'identità del sistema operativo del tuo PC e del tuo telefono, trova 6 estensioni diverse nella cartella Download e disegna l'albero delle cartelle per la scuola. Chiudi con un breve verdetto motivato. Consegna il file so-cognome.odt (oppure .pdf).", "due_date": null, "planned_due": "2026-11-11", "topic": "Il software di base: il sistema operativo", "pdf_url": "contenuti/compiti/sistema-operativo.pdf"}, {"class_id": "1d", "title": "Il neurone che decide come te", "description": "Costruisci in LibreOffice Calc un neurone artificiale con 4 ingressi, pesi e soglia che prende una tua decisione quotidiana. Provalo su 8 situazioni reali e addestralo cambiando i pesi finché indovina almeno 7 volte su 8, poi scrivi una breve riflessione. Consegna il file neurone-cognome.ods.", "due_date": null, "planned_due": "2026-11-16", "topic": "L'intelligenza artificiale", "pdf_url": "contenuti/compiti/intelligenza-artificiale.pdf"}, {"class_id": "1d", "title": "Il bot del nuovo compagno", "description": "Costruisci in Calc un chatbot a regole con 8 parole chiave e una risposta di riserva che aiuta un compagno appena arrivato a orientarsi a scuola. Mettilo alla prova con 6 messaggi in un secondo foglio e spiega che cosa farebbe meglio, e che cosa peggio, un chatbot con modello linguistico. Consegna il file chatbot-cognome.ods; non serve usare chatbot online.", "due_date": null, "planned_due": "2026-11-18", "topic": "Introduzione ai chatbot AI", "pdf_url": "contenuti/compiti/chatbot-ai.pdf"}, {"class_id": "1d", "title": "La copertina che non esiste ancora", "description": "Progetta la copertina di un libro, film o serie che conosci: scrivi 3 prompt completi in tre stili diversi con i loro prompt negativi, disegna lo schizzo dell'immagine che ti aspetti e scrivi l'etichetta di trasparenza e una breve riflessione su chi ne è l'autore. Consegna il file copertina-cognome.pdf esportato da Writer; non serve usare generatori di immagini.", "due_date": null, "planned_due": "2026-11-23", "topic": "Creazione di immagini con AI", "pdf_url": "contenuti/compiti/immagini-con-ai.pdf"}, {"class_id": "1d", "title": "La guida di sopravvivenza", "description": "Scrivi una piccola guida per chi arriverà in prima il prossimo anno, con frontespizio, almeno 3 capitoli con gli stili Titolo 1 e Titolo 2, sommario automatico, numero di pagina, filigrana ed elenchi. Ogni capitolo inizia su una pagina nuova. Consegna il file guida-cognome.pdf.", "due_date": null, "planned_due": "2026-11-26", "topic": "Documenti con Word e Writer", "pdf_url": "contenuti/compiti/word-e-writer.pdf"}, {"class_id": "1d", "title": "Il modulo a prova di errore", "description": "Progetta il modulo di iscrizione a un evento che organizzi tu, con almeno 6 controlli di 4 tipi diversi e pulsanti di scelta che si escludono a vicenda. Esportalo come PDF compilabile e provalo nel browser. Consegna il file modulo-cognome.pdf.", "due_date": null, "planned_due": "2026-11-30", "topic": "La gestione dei moduli", "pdf_url": "contenuti/compiti/moduli-compilabili.pdf"}, {"class_id": "1d", "title": "Più bravo della macchina", "description": "Correggi con Traccia modifiche e commenti i tre errori di un paragrafo su Ada Lovelace scritto da un'AI, poi scrivi un riassunto di 70-90 parole e una versione per un bambino di 9 anni. Indica fonti e strumenti usati; non serve usare un chatbot. Consegna il file lovelace-cognome.odt.", "due_date": null, "planned_due": "2026-12-03", "topic": "Applicare l'intelligenza artificiale in Word", "pdf_url": "contenuti/compiti/ai-in-word.pdf"}, {"class_id": "1d", "title": "Tre minuti per un'invenzione", "description": "Prepara una presentazione di 6-8 slide su un'invenzione o una persona che ha cambiato l'informatica, con schema coerente, immagini con fonte e note del relatore per ogni slide. Provala ad alta voce restando tra 2 minuti e mezzo e 3 minuti e mezzo. Consegna il file invenzione-cognome.odp.", "due_date": null, "planned_due": "2026-12-09", "topic": "Presentazioni con PowerPoint e Impress", "pdf_url": "contenuti/compiti/presentazioni.pdf"}, {"class_id": "1d", "title": "La mia settimana in numeri", "description": "Per una settimana annota almeno 20 attività con categoria e minuti, poi in Calc calcola per ogni categoria il numero di attività con CONTA.SE, i minuti con SOMMA.SE e l'incidenza percentuale. Aggiungi un'etichetta con SE e colora le incidenze sopra il 20%. Consegna il file settimana-cognome.ods.", "due_date": null, "planned_due": "2026-12-11", "topic": "I fogli elettronici Excel e Calc", "pdf_url": "contenuti/compiti/fogli-elettronici.pdf"}, {"class_id": "1d", "title": "Il grafico onesto e il grafico bugiardo", "description": "Raccogli per 7 giorni un dato della tua vita e disegnalo in Calc con un grafico a linee o a colonne; crea una torta della tua giornata tipo. Poi copia il primo grafico e rendilo ingannevole cambiando la scala dell'asse, spiegando il trucco. Consegna il file grafici-cognome.ods.", "due_date": null, "planned_due": "2026-12-16", "topic": "I grafici dei fogli di calcolo", "pdf_url": "contenuti/compiti/grafici.pdf"}, {"class_id": "1d", "title": "Il database della mia collezione", "description": "Crea in LibreOffice Base un database su una tua passione, con una tabella di almeno 6 campi di tipo adatto, una chiave primaria e almeno 10 record. Crea e salva 3 query: con un criterio di testo, con un criterio numerico e un ordinamento, con due criteri insieme. Consegna il file collezione-cognome.odb.", "due_date": null, "planned_due": "2026-12-18", "topic": "I database Access e Base", "pdf_url": "contenuti/compiti/database.pdf"}, {"class_id": "1d", "title": "Il mio biglietto animato", "description": "Programma in Scratch un biglietto di auguri per una persona vera, con sfondo, almeno 2 sprite che partono dalla loro posizione iniziale, un'animazione con i costumi, battute nei fumetti, un suono e uno sprite che reagisce al clic. Consegna il file biglietto-cognome.sb3.", "due_date": null, "planned_due": "2027-01-07", "topic": "Programmiamo con Scratch", "pdf_url": "contenuti/compiti/scratch.pdf"}, {"class_id": "1d", "title": "Fuga dal labirinto", "description": "Disegna un labirinto in Scratch e guida un eroe con le frecce: se tocca un muro torna alla partenza, se raggiunge l'uscita vince. Aggiungi un nemico che va avanti e indietro e fai provare il gioco a qualcuno di casa. Consegna il file labirinto-cognome.sb3.", "due_date": null, "planned_due": "2027-01-12", "topic": "Videogiochi con sensori", "pdf_url": "contenuti/compiti/videogiochi-scratch.pdf"}, {"class_id": "1d", "title": "Il quiz del campione", "description": "Costruisci in Scratch un quiz di 5 domande su un argomento a scelta: il gatto chiede il nome, controlla le risposte con se… altrimenti, tiene il punteggio in una variabile e alla fine dà un giudizio. Almeno una domanda è un calcolo fatto da Scratch. Consegna il file quiz-cognome.sb3.", "due_date": null, "planned_due": "2027-01-14", "topic": "Variabili e operazioni di I/O", "pdf_url": "contenuti/compiti/variabili-scratch.pdf"}, {"class_id": "1d", "title": "Il mio frasario parlante", "description": "Crea con App Inventor un frasario per un viaggio all'estero: almeno 4 pulsanti con frasi in italiano che mostrano e pronunciano la traduzione nella lingua che studi, più una casella per far leggere qualunque frase. Collauda l'app sul telefono con il Companion. Consegna il file frasario-cognome.aia.", "due_date": null, "planned_due": "2027-01-19", "topic": "Realizziamo app per cellulari con App Inventor", "pdf_url": "contenuti/compiti/app-inventor.pdf"}, {"class_id": "1d", "title": "Acchiappa… a modo mio", "description": "Personalizza il gioco del panino fatto in classe: cambia il tema e lo sfondo, aggiungi un pulsante Ricomincia che azzera punti e tempo e riaccende i timer, e inventa una regola nuova (trappola, record o secondo livello). Collauda almeno 3 partite di fila. Consegna il file acchiappa-cognome.aia.", "due_date": null, "planned_due": "2027-01-22", "topic": "Un gioco di animazione per cellulari", "pdf_url": "contenuti/compiti/gioco-app-inventor.pdf"}, {"class_id": "1d", "title": "Diario di un addestratore di AI", "description": "Addestra su Machine Learning for Kids un modello di testo con 2 o 3 etichette e almeno 10 esempi ciascuna, provalo con 10 frasi nuove e calcola l'accuratezza. Poi sbilancia i dati, riaddestra e descrivi che cosa cambia. Consegna il documento ai-cognome.pdf.", "due_date": null, "planned_due": "2027-01-26", "topic": "Applicazioni con l'intelligenza artificiale", "pdf_url": "contenuti/compiti/app-con-ai.pdf"}, {"class_id": "1d", "title": "Il semaforo", "description": "In Tinkercad monta tre LED con le loro resistenze sui pin 11, 12 e 13 e programma la sequenza verde 5 secondi, giallo 2, rosso 5, un LED alla volta. Prepara un documento con gli screenshot del circuito e del codice, la tabella dei tempi e un errore corretto. Consegna il file semaforo-cognome.pdf.", "due_date": null, "planned_due": "2027-01-29", "topic": "Arduino e Tinkercad", "pdf_url": "contenuti/compiti/arduino-tinkercad.pdf"}, {"class_id": "1d", "title": "L'algoritmo a prova di robot", "description": "Scegli un'azione di tutti i giorni, analizza il problema e scrivi l'algoritmo in pseudocodice con almeno un SE e un RIPETI. Fallo eseguire alla lettera a un familiare-robot, annota i problemi emersi e scrivi la versione corretta. Consegna il file algoritmo-robot-cognome.pdf.", "due_date": null, "planned_due": "2027-02-03", "topic": "Conosciamo gli algoritmi e i linguaggi", "pdf_url": "contenuti/compiti/algoritmi.pdf"}, {"class_id": "1d", "title": "Il flow chart della pizzata", "description": "Progetta l'algoritmo che divide il conto della pizzeria aggiungendo un coperto fisso a persona: scrivi l'analisi, disegna il flow chart con le forme corrette e fai la tabella di traccia con due prove. Rispondi alla domanda sul caso con 0 persone. Consegna il file pizzata-cognome.pdf.", "due_date": null, "planned_due": "2027-02-05", "topic": "Codifichiamo gli algoritmi con i flow chart", "pdf_url": "contenuti/compiti/flow-chart.pdf"}, {"class_id": "1d", "title": "Il contatore del tempo di schermo", "description": "Costruisci in Flowgorithm un programma che legge i minuti di schermo al giorno e calcola le ore e i giorni interi all'anno, usando una costante per i giorni dell'anno. Provalo con tre valori e annota i risultati in un blocco Comment. Consegna il file schermo-anno-cognome.fprg.", "due_date": null, "planned_due": "2027-02-10", "topic": "Realizziamo i flow chart con Flowgorithm", "pdf_url": "contenuti/compiti/flowgorithm.pdf"}, {"class_id": "1d", "title": "Il controllore delle montagne russe", "description": "In Flowgorithm scrivi il programma che decide chi può salire su un'attrazione in base all'altezza (selezione doppia) e avvisa i più giovani che serve un adulto (selezione semplice annidata). Prova i quattro casi indicati, compreso il caso limite, e annotali in un blocco Comment. Consegna il file giostra-cognome.fprg.", "due_date": null, "planned_due": "2027-02-15", "topic": "L'istruzione di selezione", "pdf_url": "contenuti/compiti/selezione-flowgorithm.pdf"}, {"class_id": "1d", "title": "Il salvadanaio intelligente", "description": "In Flowgorithm calcola quante settimane di paghetta servono per raggiungere un obiettivo di spesa: controlla l'input con un ciclo Do e usa un ciclo While con contatore e accumulatore. Prova i tre casi indicati e rispondi alla domanda finale in un blocco Comment. Consegna il file salvadanaio-cognome.fprg.", "due_date": null, "planned_due": "2027-02-17", "topic": "L'istruzione di iterazione", "pdf_url": "contenuti/compiti/iterazione-flowgorithm.pdf"}, {"class_id": "1d", "title": "Il mio biglietto da visita in C", "description": "Scrivi un programma C che stampa un biglietto da visita incorniciato di almeno 5 righe, calcola con due variabili int le ore di scuola in un anno e scambia due variabili usando aux, stampandole prima e dopo. Consegna il file biglietto-cognome.c.", "due_date": null, "planned_due": "2027-02-22", "topic": "Programmiamo in C e C++", "pdf_url": "contenuti/compiti/c-cpp-primi-passi.pdf"}, {"class_id": "1d", "title": "Il conto della pizzeria", "description": "Scrivi un programma C che chiede con scanf numero e prezzo di pizze e bibite e quanti amici pagano, poi stampa uno scontrino ordinato con totale e quota a testa, tutti i prezzi con 2 decimali. Consegna il file pizzeria-cognome.c.", "due_date": null, "planned_due": "2027-02-25", "topic": "L'input e l'output dei dati", "pdf_url": "contenuti/compiti/input-output-c.pdf"}, {"class_id": "1d", "title": "Il quiz show in C", "description": "Scrivi un programma C con 3 domande a risposta numerica che controlla ogni risposta con if ed else, conta i punti e stampa un messaggio finale; una domanda accetta due risposte con ||, e un voto da 1 a 10 viene controllato. Consegna il file quiz-cognome.c.", "due_date": null, "planned_due": "2027-03-01", "topic": "L'istruzione di selezione semplice e doppia", "pdf_url": "contenuti/compiti/selezione-c.pdf"}, {"class_id": "1d", "title": "La fabbrica di disegni", "description": "Scrivi un programma C che legge una dimensione da 1 a 9 (controllandola) e disegna con i cicli for un quadrato, un conto alla rovescia con passo negativo, un triangolo di numeri e una scacchiera. Consegna il file disegni-cognome.c.", "due_date": null, "planned_due": "2027-03-04", "topic": "L'istruzione di iterazione definita", "pdf_url": "contenuti/compiti/ciclo-for-c.pdf"}, {"class_id": "1d", "title": "Tabelline: sopravvivi finché puoi", "description": "Scrivi in C un gioco che con rand propone moltiplicazioni casuali e, con un ciclo while, continua finché rispondi giusto o arrivi a 10 punti, poi stampa il punteggio. Fai giocare anche un'altra persona e scrivi i punteggi in un commento. Consegna il file tabelline-cognome.c.", "due_date": null, "planned_due": "2027-03-09", "topic": "L'istruzione di iterazione indefinita", "pdf_url": "contenuti/compiti/ciclo-while-c.pdf"}, {"class_id": "1d", "title": "Il negozio a funzioni", "description": "Scrivi in C il programma della cassa per i saldi dei videogiochi, con i prototipi e tre sottoprogrammi: sconto, conviene e la procedura cornice. Provalo con tre casi diversi e riporta i risultati in un commento in fondo al file. Consegna il file negozio-cognome.c.", "due_date": null, "planned_due": "2027-03-11", "topic": "Funzioni e procedure", "pdf_url": "contenuti/compiti/funzioni-c.pdf"}, {"class_id": "1d", "title": "Il podio della gara", "description": "Scrivi in C le funzioni scambia e ordina3, che con i puntatori mettono in ordine i tempi di tre corridori, e stampa il podio. Prova almeno quattro terne e rispondi in un commento a due domande su passaggio per valore e uso della & in scanf. Consegna il file podio-cognome.c.", "due_date": null, "planned_due": "2027-03-16", "topic": "Il passaggio dei parametri alle funzioni", "pdf_url": "contenuti/compiti/parametri-c.pdf"}, {"class_id": "1d", "title": "Sette giorni di passi", "description": "Scrivi in C un programma che carica in un vettore i passi di 7 giorni, con funzioni per media, giorni sopra la media e giorno record, e una procedura che disegna un grafico a barre di asterischi. In un commento riporta i tuoi dati e una breve riflessione. Consegna il file passi-cognome.c.", "due_date": null, "planned_due": "2027-03-19", "topic": "Gli array monodimensionali o vettori", "pdf_url": "contenuti/compiti/vettori-c.pdf"}, {"class_id": "1d", "title": "La stazione meteo guasta", "description": "Analizza in C le temperature di 15 giorni: conta gli errori del sensore (-99), riparali con il valore del giorno prima, calcola media e giorni caldi e cerca il primo giorno con una temperatura data. Rispondi in un commento sul caso peggiore della ricerca. Consegna il file meteo-cognome.c.", "due_date": null, "planned_due": "2027-03-23", "topic": "La ricerca in un vettore", "pdf_url": "contenuti/compiti/ricerca-vettore.pdf"}, {"class_id": "1d", "title": "La gara degli algoritmi", "description": "Metti in un vettore le durate in secondi di 10 canzoni e ordinale con selezione e inserzione, stampandole in minuti:secondi e contando i confronti. Ripeti la gara su playlist già ordinata e al contrario e riporta i sei risultati in un commento, spiegando chi vince. Consegna il file playlist-cognome.c.", "due_date": null, "planned_due": "2027-04-01", "topic": "L'ordinamento degli elementi di un vettore", "pdf_url": "contenuti/compiti/ordinamento-vettore.pdf"}, {"class_id": "1d", "title": "La cassa della pizzata di classe", "description": "Scrivi un programma Python che chiede persone, pizze e bibite, calcola il totale con un accumulatore e la quota a testa, e con // e % dice quanti tavoli da 6 sono pieni. In fondo aggiungi un commento con l'output dell'esempio. Consegna il file pizzata-cognome.py.", "due_date": null, "planned_due": "2027-04-06", "topic": "Introduzione a Python", "pdf_url": "contenuti/compiti/python-intro.pdf"}, {"class_id": "1d", "title": "La biglietteria del parco divertimenti", "description": "Scrivi un programma che legge età, altezza e giorno e applica le regole del parco: prezzo con una selezione doppia, supplemento del weekend con or e accesso alle montagne russe con and. Prova i 4 casi della scheda e scrivi l'esito in un commento. Consegna il file parco-cognome.py.", "due_date": null, "planned_due": "2027-04-08", "topic": "Python: la selezione semplice e doppia", "pdf_url": "contenuti/compiti/python-selezione.pdf"}, {"class_id": "1d", "title": "La sfida delle tabelline", "description": "Programma un gioco in cui il computer fa domande casuali sulle tabelline finché il giocatore ha vite: controlla con un while il numero di vite scelto e conta i punti. Fai giocare 3 persone e scrivi i loro punteggi in un commento. Consegna il file tabelline-cognome.py.", "due_date": null, "planned_due": "2027-04-13", "topic": "Python: l'iterazione indefinita (while)", "pdf_url": "contenuti/compiti/python-while.pdf"}, {"class_id": "1d", "title": "La fabbrica delle figure", "description": "Con cicli for annidati stampa con i caratteri un quadrato, un triangolo e una scacchiera di lato scelto dall'utente, poi inventa una quarta figura e spiega in un commento come funziona. Consegna il file figure-cognome.py.", "due_date": null, "planned_due": "2027-04-16", "topic": "Python: l'iterazione definita (for)", "pdf_url": "contenuti/compiti/python-for.pdf"}, {"class_id": "1d", "title": "Il carrello della spesa online", "description": "Costruisci un carrello online con le funzioni prezzo_scontato, spedizione e leggi_numero e un main che legge gli articoli con un ciclo for e stampa subtotale, spedizione e totale, usando il punto di ingresso. Solo main può stampare. Consegna il file carrello-cognome.py.", "due_date": null, "planned_due": "2027-04-20", "topic": "Python: le funzioni", "pdf_url": "contenuti/compiti/python-funzioni.pdf"}, {"class_id": "1d", "title": "La mia classifica dei film", "description": "Con due liste parallele riempite da un while con valore sentinella, raccogli almeno 6 titoli con il loro voto, stampa la classifica, il preferito e la media. Copia l'output in un commento in fondo al file. Consegna il file classifica-cognome.py.", "due_date": null, "planned_due": "2027-04-23", "topic": "Python: le liste", "pdf_url": "contenuti/compiti/python-liste.pdf"}, {"class_id": "1d", "title": "Caccia ai segnali di casa", "description": "Trova in casa almeno 8 dispositivi che comunicano e, in una tabella di Calc, indica mezzo trasmissivo, tipo di segnale e possibili disturbi. Misura la velocità della linea con fast.com e calcola con le formule i tempi di download di tre file. Consegna il file segnali-casa-cognome.ods.", "due_date": null, "planned_due": "2027-04-27", "topic": "Introduzione alle telecomunicazioni", "pdf_url": "contenuti/compiti/telecomunicazioni.pdf"}, {"class_id": "1d", "title": "La mappa della rete di casa", "description": "Elenca almeno 6 dispositivi di casa collegati in rete e disegna la mappa della tua LAN con LibreOffice Draw, distinguendo cavo e Wi-Fi. Indica tipo di rete e topologia e spiega che cosa funziona ancora se cade internet. Consegna il file rete-casa-cognome.pdf.", "due_date": null, "planned_due": "2027-04-30", "topic": "Che cosa sono le reti", "pdf_url": "contenuti/compiti/reti.pdf"}, {"class_id": "1d", "title": "Il piano di indirizzamento", "description": "Dividi la rete 192.168.50.0/24 in 4 sottoreti uguali per quattro ambienti della scuola. In Calc compila la tabella con indirizzo di rete, primo e ultimo host, broadcast e subnet mask, e rispondi alle domande sui dispositivi. Consegna il file piano-ip-cognome.ods.", "due_date": null, "planned_due": "2027-05-05", "topic": "Come si usano le reti", "pdf_url": "contenuti/compiti/indirizzi-ip.pdf"}, {"class_id": "1d", "title": "Il mio piano di sicurezza", "description": "Scegli 6 minacce per la tua vita digitale e valutale in Calc con probabilità, impatto, rischio e livello calcolati con le formule, poi proponi una contromisura per ognuna. In un secondo foglio scrivi 5 regole di sicurezza per un familiare. Consegna il file sicurezza-cognome.ods.", "due_date": null, "planned_due": "2027-05-07", "topic": "La sicurezza nelle reti", "pdf_url": "contenuti/compiti/sicurezza-reti.pdf"}, {"class_id": "1d", "title": "Agente segreto per un giorno", "description": "Cifra con CyberChef un messaggio di almeno 25 parole usando il metodo di Cesare, poi conta in Calc le frequenze delle lettere e prova a scoprire la chiave come un crittoanalista. Rispondi a due domande su Bellaso e sulla chiave pubblica. Consegna il file agente-segreto-cognome.ods.", "due_date": null, "planned_due": "2027-05-12", "topic": "Principi di crittografia", "pdf_url": "contenuti/compiti/crittografia.pdf"}, {"class_id": "1d", "title": "Il controllo di sicurezza dei miei account", "description": "Ispeziona 4 tuoi account (fattori usati, verifica in due passaggi, riuso) senza scrivere password, crea una passphrase di prova con i dadi e calcola quante combinazioni ha rispetto al metodo vero. Chiudi con 5 regole di sicurezza per la tua famiglia. Consegna il file account-cognome.odt.", "due_date": null, "planned_due": "2027-05-17", "topic": "L'autenticazione dell'utente", "pdf_url": "contenuti/compiti/autenticazione.pdf"}, {"class_id": "1d", "title": "Il patto firmato", "description": "Scrivi un patto digitale con la tua famiglia, calcolane l'impronta SHA-256 e firmalo in Calc con le chiavi giocattolo della lezione, poi verifica che cosa succede se il testo cambia. Ispeziona i certificati di 3 siti e intervista un adulto su SPID, PEC e firma digitale. Consegna il file patto-firmato-cognome.ods.", "due_date": null, "planned_due": "2027-05-19", "topic": "Firma elettronica e certificati digitali", "pdf_url": "contenuti/compiti/firma-digitale.pdf"}, {"class_id": "1d", "title": "Una mostra a licenza libera", "description": "Prepara una mostra digitale di 6 slide su un tema a scelta con quattro immagini davvero utilizzabili (licenze Creative Commons o pubblico dominio), ognuna con l'attribuzione TASL, più una tua opera con la licenza che scegli tu. Consegna il file mostra-libera-cognome.odp.", "due_date": null, "planned_due": "2027-05-24", "topic": "Il diritto d'autore digitale", "pdf_url": "contenuti/compiti/diritto-autore.pdf"}, {"class_id": "1d", "title": "Il poster che fa la differenza", "description": "Crea un poster A4 per una campagna della scuola contro il cyberbullismo: uno slogan positivo, le 5 mosse da fare, tre frasi di sostegno per un compagno preso di mira e i contatti utili, con un'immagine tua o a licenza libera. Consegna il file poster-cognome.pdf.", "due_date": null, "planned_due": "2027-05-27", "topic": "I rischi della rete: cyberbullismo e grooming", "pdf_url": "contenuti/compiti/cyberbullismo.pdf"}, {"class_id": "1d", "title": "L'informativa che tutti capiscono", "description": "Con un genitore controlla i permessi di 5 app sul telefono e valuta quali servono davvero. Poi scrivi in modo chiaro l'informativa privacy di CompitiBuddy, un'app inventata, rispondendo alle 6 domande del GDPR e aggiungendo la regola per chi ha meno di 14 anni. Consegna il file privacy-cognome.odt.", "due_date": null, "planned_due": "2027-05-31", "topic": "La privacy e la protezione dei dati personali", "pdf_url": "contenuti/compiti/privacy.pdf"}, {"class_id": "1d", "title": "La mia postazione da dieci e lode", "description": "Misura il posto dove studi al computer e valuta ogni misura con le formule SE di Calc, registra per due giorni le sessioni davanti agli schermi e le pause, poi proponi tre miglioramenti concreti. Consegna il file postazione-cognome.ods.", "due_date": null, "planned_due": "2027-06-04", "topic": "La sicurezza e l'ergonomia", "pdf_url": "contenuti/compiti/ergonomia.pdf"}, {"class_id": "1e", "title": "Il diario dei miei dati", "description": "Per un giorno annota almeno 10 dati che produci o che i tuoi dispositivi raccolgono e organizzali in una tabella di Calc, indicando la fase del ciclo input-elaborazione-output. Trasforma 3 dati in informazioni utili e scrivi una breve riflessione. Consegna il file diario-dati-cognome.ods.", "due_date": null, "planned_due": "2026-10-30", "topic": "La tecnologia dell'informazione", "pdf_url": "contenuti/compiti/tecnologia-informazione.pdf"}, {"class_id": "1e", "title": "La mia palette in esadecimale", "description": "Scegli un tema che ti piace e 5 colori che lo rappresentano, trova il loro codice #RRGGBB e converti a mano in decimale le tre luci e in binario il rosso. Verifica i calcoli con le funzioni di Calc e colora le celle. Consegna il file palette-cognome.ods.", "due_date": null, "planned_due": "2026-11-04", "topic": "I sistemi di numerazione binario, ottale ed esadecimale", "pdf_url": "contenuti/compiti/sistemi-di-numerazione.pdf"}, {"class_id": "1e", "title": "Le regole del gioco in logica", "description": "Scegli un gioco o uno sport, scrivi 4 proposizioni semplici e 3 regole che le combinano con AND, OR e NOT. Costruisci in Calc la tabella di verità di una regola con 3 proposizioni e spiega le righe vere. Consegna il file logica-cognome.ods.", "due_date": null, "planned_due": "2026-11-06", "topic": "La logica", "pdf_url": "contenuti/compiti/la-logica.pdf"}, {"class_id": "1e", "title": "Detective del sistema operativo", "description": "Compila la carta d'identità del sistema operativo del tuo PC e del tuo telefono, trova 6 estensioni diverse nella cartella Download e disegna l'albero delle cartelle per la scuola. Chiudi con un breve verdetto motivato. Consegna il file so-cognome.odt (oppure .pdf).", "due_date": null, "planned_due": "2026-11-11", "topic": "Il software di base: il sistema operativo", "pdf_url": "contenuti/compiti/sistema-operativo.pdf"}, {"class_id": "1e", "title": "Il neurone che decide come te", "description": "Costruisci in LibreOffice Calc un neurone artificiale con 4 ingressi, pesi e soglia che prende una tua decisione quotidiana. Provalo su 8 situazioni reali e addestralo cambiando i pesi finché indovina almeno 7 volte su 8, poi scrivi una breve riflessione. Consegna il file neurone-cognome.ods.", "due_date": null, "planned_due": "2026-11-16", "topic": "L'intelligenza artificiale", "pdf_url": "contenuti/compiti/intelligenza-artificiale.pdf"}, {"class_id": "1e", "title": "Il bot del nuovo compagno", "description": "Costruisci in Calc un chatbot a regole con 8 parole chiave e una risposta di riserva che aiuta un compagno appena arrivato a orientarsi a scuola. Mettilo alla prova con 6 messaggi in un secondo foglio e spiega che cosa farebbe meglio, e che cosa peggio, un chatbot con modello linguistico. Consegna il file chatbot-cognome.ods; non serve usare chatbot online.", "due_date": null, "planned_due": "2026-11-18", "topic": "Introduzione ai chatbot AI", "pdf_url": "contenuti/compiti/chatbot-ai.pdf"}, {"class_id": "1e", "title": "La copertina che non esiste ancora", "description": "Progetta la copertina di un libro, film o serie che conosci: scrivi 3 prompt completi in tre stili diversi con i loro prompt negativi, disegna lo schizzo dell'immagine che ti aspetti e scrivi l'etichetta di trasparenza e una breve riflessione su chi ne è l'autore. Consegna il file copertina-cognome.pdf esportato da Writer; non serve usare generatori di immagini.", "due_date": null, "planned_due": "2026-11-23", "topic": "Creazione di immagini con AI", "pdf_url": "contenuti/compiti/immagini-con-ai.pdf"}, {"class_id": "1e", "title": "La guida di sopravvivenza", "description": "Scrivi una piccola guida per chi arriverà in prima il prossimo anno, con frontespizio, almeno 3 capitoli con gli stili Titolo 1 e Titolo 2, sommario automatico, numero di pagina, filigrana ed elenchi. Ogni capitolo inizia su una pagina nuova. Consegna il file guida-cognome.pdf.", "due_date": null, "planned_due": "2026-11-26", "topic": "Documenti con Word e Writer", "pdf_url": "contenuti/compiti/word-e-writer.pdf"}, {"class_id": "1e", "title": "Il modulo a prova di errore", "description": "Progetta il modulo di iscrizione a un evento che organizzi tu, con almeno 6 controlli di 4 tipi diversi e pulsanti di scelta che si escludono a vicenda. Esportalo come PDF compilabile e provalo nel browser. Consegna il file modulo-cognome.pdf.", "due_date": null, "planned_due": "2026-11-30", "topic": "La gestione dei moduli", "pdf_url": "contenuti/compiti/moduli-compilabili.pdf"}, {"class_id": "1e", "title": "Più bravo della macchina", "description": "Correggi con Traccia modifiche e commenti i tre errori di un paragrafo su Ada Lovelace scritto da un'AI, poi scrivi un riassunto di 70-90 parole e una versione per un bambino di 9 anni. Indica fonti e strumenti usati; non serve usare un chatbot. Consegna il file lovelace-cognome.odt.", "due_date": null, "planned_due": "2026-12-03", "topic": "Applicare l'intelligenza artificiale in Word", "pdf_url": "contenuti/compiti/ai-in-word.pdf"}, {"class_id": "1e", "title": "Tre minuti per un'invenzione", "description": "Prepara una presentazione di 6-8 slide su un'invenzione o una persona che ha cambiato l'informatica, con schema coerente, immagini con fonte e note del relatore per ogni slide. Provala ad alta voce restando tra 2 minuti e mezzo e 3 minuti e mezzo. Consegna il file invenzione-cognome.odp.", "due_date": null, "planned_due": "2026-12-09", "topic": "Presentazioni con PowerPoint e Impress", "pdf_url": "contenuti/compiti/presentazioni.pdf"}, {"class_id": "1e", "title": "La mia settimana in numeri", "description": "Per una settimana annota almeno 20 attività con categoria e minuti, poi in Calc calcola per ogni categoria il numero di attività con CONTA.SE, i minuti con SOMMA.SE e l'incidenza percentuale. Aggiungi un'etichetta con SE e colora le incidenze sopra il 20%. Consegna il file settimana-cognome.ods.", "due_date": null, "planned_due": "2026-12-11", "topic": "I fogli elettronici Excel e Calc", "pdf_url": "contenuti/compiti/fogli-elettronici.pdf"}, {"class_id": "1e", "title": "Il grafico onesto e il grafico bugiardo", "description": "Raccogli per 7 giorni un dato della tua vita e disegnalo in Calc con un grafico a linee o a colonne; crea una torta della tua giornata tipo. Poi copia il primo grafico e rendilo ingannevole cambiando la scala dell'asse, spiegando il trucco. Consegna il file grafici-cognome.ods.", "due_date": null, "planned_due": "2026-12-16", "topic": "I grafici dei fogli di calcolo", "pdf_url": "contenuti/compiti/grafici.pdf"}, {"class_id": "1e", "title": "Il database della mia collezione", "description": "Crea in LibreOffice Base un database su una tua passione, con una tabella di almeno 6 campi di tipo adatto, una chiave primaria e almeno 10 record. Crea e salva 3 query: con un criterio di testo, con un criterio numerico e un ordinamento, con due criteri insieme. Consegna il file collezione-cognome.odb.", "due_date": null, "planned_due": "2026-12-18", "topic": "I database Access e Base", "pdf_url": "contenuti/compiti/database.pdf"}, {"class_id": "1e", "title": "Il mio biglietto animato", "description": "Programma in Scratch un biglietto di auguri per una persona vera, con sfondo, almeno 2 sprite che partono dalla loro posizione iniziale, un'animazione con i costumi, battute nei fumetti, un suono e uno sprite che reagisce al clic. Consegna il file biglietto-cognome.sb3.", "due_date": null, "planned_due": "2027-01-07", "topic": "Programmiamo con Scratch", "pdf_url": "contenuti/compiti/scratch.pdf"}, {"class_id": "1e", "title": "Fuga dal labirinto", "description": "Disegna un labirinto in Scratch e guida un eroe con le frecce: se tocca un muro torna alla partenza, se raggiunge l'uscita vince. Aggiungi un nemico che va avanti e indietro e fai provare il gioco a qualcuno di casa. Consegna il file labirinto-cognome.sb3.", "due_date": null, "planned_due": "2027-01-12", "topic": "Videogiochi con sensori", "pdf_url": "contenuti/compiti/videogiochi-scratch.pdf"}, {"class_id": "1e", "title": "Il quiz del campione", "description": "Costruisci in Scratch un quiz di 5 domande su un argomento a scelta: il gatto chiede il nome, controlla le risposte con se… altrimenti, tiene il punteggio in una variabile e alla fine dà un giudizio. Almeno una domanda è un calcolo fatto da Scratch. Consegna il file quiz-cognome.sb3.", "due_date": null, "planned_due": "2027-01-14", "topic": "Variabili e operazioni di I/O", "pdf_url": "contenuti/compiti/variabili-scratch.pdf"}, {"class_id": "1e", "title": "Il mio frasario parlante", "description": "Crea con App Inventor un frasario per un viaggio all'estero: almeno 4 pulsanti con frasi in italiano che mostrano e pronunciano la traduzione nella lingua che studi, più una casella per far leggere qualunque frase. Collauda l'app sul telefono con il Companion. Consegna il file frasario-cognome.aia.", "due_date": null, "planned_due": "2027-01-19", "topic": "Realizziamo app per cellulari con App Inventor", "pdf_url": "contenuti/compiti/app-inventor.pdf"}, {"class_id": "1e", "title": "Acchiappa… a modo mio", "description": "Personalizza il gioco del panino fatto in classe: cambia il tema e lo sfondo, aggiungi un pulsante Ricomincia che azzera punti e tempo e riaccende i timer, e inventa una regola nuova (trappola, record o secondo livello). Collauda almeno 3 partite di fila. Consegna il file acchiappa-cognome.aia.", "due_date": null, "planned_due": "2027-01-22", "topic": "Un gioco di animazione per cellulari", "pdf_url": "contenuti/compiti/gioco-app-inventor.pdf"}, {"class_id": "1e", "title": "Diario di un addestratore di AI", "description": "Addestra su Machine Learning for Kids un modello di testo con 2 o 3 etichette e almeno 10 esempi ciascuna, provalo con 10 frasi nuove e calcola l'accuratezza. Poi sbilancia i dati, riaddestra e descrivi che cosa cambia. Consegna il documento ai-cognome.pdf.", "due_date": null, "planned_due": "2027-01-26", "topic": "Applicazioni con l'intelligenza artificiale", "pdf_url": "contenuti/compiti/app-con-ai.pdf"}, {"class_id": "1e", "title": "Il semaforo", "description": "In Tinkercad monta tre LED con le loro resistenze sui pin 11, 12 e 13 e programma la sequenza verde 5 secondi, giallo 2, rosso 5, un LED alla volta. Prepara un documento con gli screenshot del circuito e del codice, la tabella dei tempi e un errore corretto. Consegna il file semaforo-cognome.pdf.", "due_date": null, "planned_due": "2027-01-29", "topic": "Arduino e Tinkercad", "pdf_url": "contenuti/compiti/arduino-tinkercad.pdf"}, {"class_id": "1e", "title": "L'algoritmo a prova di robot", "description": "Scegli un'azione di tutti i giorni, analizza il problema e scrivi l'algoritmo in pseudocodice con almeno un SE e un RIPETI. Fallo eseguire alla lettera a un familiare-robot, annota i problemi emersi e scrivi la versione corretta. Consegna il file algoritmo-robot-cognome.pdf.", "due_date": null, "planned_due": "2027-02-03", "topic": "Conosciamo gli algoritmi e i linguaggi", "pdf_url": "contenuti/compiti/algoritmi.pdf"}, {"class_id": "1e", "title": "Il flow chart della pizzata", "description": "Progetta l'algoritmo che divide il conto della pizzeria aggiungendo un coperto fisso a persona: scrivi l'analisi, disegna il flow chart con le forme corrette e fai la tabella di traccia con due prove. Rispondi alla domanda sul caso con 0 persone. Consegna il file pizzata-cognome.pdf.", "due_date": null, "planned_due": "2027-02-05", "topic": "Codifichiamo gli algoritmi con i flow chart", "pdf_url": "contenuti/compiti/flow-chart.pdf"}, {"class_id": "1e", "title": "Il contatore del tempo di schermo", "description": "Costruisci in Flowgorithm un programma che legge i minuti di schermo al giorno e calcola le ore e i giorni interi all'anno, usando una costante per i giorni dell'anno. Provalo con tre valori e annota i risultati in un blocco Comment. Consegna il file schermo-anno-cognome.fprg.", "due_date": null, "planned_due": "2027-02-10", "topic": "Realizziamo i flow chart con Flowgorithm", "pdf_url": "contenuti/compiti/flowgorithm.pdf"}, {"class_id": "1e", "title": "Il controllore delle montagne russe", "description": "In Flowgorithm scrivi il programma che decide chi può salire su un'attrazione in base all'altezza (selezione doppia) e avvisa i più giovani che serve un adulto (selezione semplice annidata). Prova i quattro casi indicati, compreso il caso limite, e annotali in un blocco Comment. Consegna il file giostra-cognome.fprg.", "due_date": null, "planned_due": "2027-02-15", "topic": "L'istruzione di selezione", "pdf_url": "contenuti/compiti/selezione-flowgorithm.pdf"}, {"class_id": "1e", "title": "Il salvadanaio intelligente", "description": "In Flowgorithm calcola quante settimane di paghetta servono per raggiungere un obiettivo di spesa: controlla l'input con un ciclo Do e usa un ciclo While con contatore e accumulatore. Prova i tre casi indicati e rispondi alla domanda finale in un blocco Comment. Consegna il file salvadanaio-cognome.fprg.", "due_date": null, "planned_due": "2027-02-17", "topic": "L'istruzione di iterazione", "pdf_url": "contenuti/compiti/iterazione-flowgorithm.pdf"}, {"class_id": "1e", "title": "Il mio biglietto da visita in C", "description": "Scrivi un programma C che stampa un biglietto da visita incorniciato di almeno 5 righe, calcola con due variabili int le ore di scuola in un anno e scambia due variabili usando aux, stampandole prima e dopo. Consegna il file biglietto-cognome.c.", "due_date": null, "planned_due": "2027-02-22", "topic": "Programmiamo in C e C++", "pdf_url": "contenuti/compiti/c-cpp-primi-passi.pdf"}, {"class_id": "1e", "title": "Il conto della pizzeria", "description": "Scrivi un programma C che chiede con scanf numero e prezzo di pizze e bibite e quanti amici pagano, poi stampa uno scontrino ordinato con totale e quota a testa, tutti i prezzi con 2 decimali. Consegna il file pizzeria-cognome.c.", "due_date": null, "planned_due": "2027-02-25", "topic": "L'input e l'output dei dati", "pdf_url": "contenuti/compiti/input-output-c.pdf"}, {"class_id": "1e", "title": "Il quiz show in C", "description": "Scrivi un programma C con 3 domande a risposta numerica che controlla ogni risposta con if ed else, conta i punti e stampa un messaggio finale; una domanda accetta due risposte con ||, e un voto da 1 a 10 viene controllato. Consegna il file quiz-cognome.c.", "due_date": null, "planned_due": "2027-03-01", "topic": "L'istruzione di selezione semplice e doppia", "pdf_url": "contenuti/compiti/selezione-c.pdf"}, {"class_id": "1e", "title": "La fabbrica di disegni", "description": "Scrivi un programma C che legge una dimensione da 1 a 9 (controllandola) e disegna con i cicli for un quadrato, un conto alla rovescia con passo negativo, un triangolo di numeri e una scacchiera. Consegna il file disegni-cognome.c.", "due_date": null, "planned_due": "2027-03-04", "topic": "L'istruzione di iterazione definita", "pdf_url": "contenuti/compiti/ciclo-for-c.pdf"}, {"class_id": "1e", "title": "Tabelline: sopravvivi finché puoi", "description": "Scrivi in C un gioco che con rand propone moltiplicazioni casuali e, con un ciclo while, continua finché rispondi giusto o arrivi a 10 punti, poi stampa il punteggio. Fai giocare anche un'altra persona e scrivi i punteggi in un commento. Consegna il file tabelline-cognome.c.", "due_date": null, "planned_due": "2027-03-09", "topic": "L'istruzione di iterazione indefinita", "pdf_url": "contenuti/compiti/ciclo-while-c.pdf"}, {"class_id": "1e", "title": "Il negozio a funzioni", "description": "Scrivi in C il programma della cassa per i saldi dei videogiochi, con i prototipi e tre sottoprogrammi: sconto, conviene e la procedura cornice. Provalo con tre casi diversi e riporta i risultati in un commento in fondo al file. Consegna il file negozio-cognome.c.", "due_date": null, "planned_due": "2027-03-11", "topic": "Funzioni e procedure", "pdf_url": "contenuti/compiti/funzioni-c.pdf"}, {"class_id": "1e", "title": "Il podio della gara", "description": "Scrivi in C le funzioni scambia e ordina3, che con i puntatori mettono in ordine i tempi di tre corridori, e stampa il podio. Prova almeno quattro terne e rispondi in un commento a due domande su passaggio per valore e uso della & in scanf. Consegna il file podio-cognome.c.", "due_date": null, "planned_due": "2027-03-16", "topic": "Il passaggio dei parametri alle funzioni", "pdf_url": "contenuti/compiti/parametri-c.pdf"}, {"class_id": "1e", "title": "Sette giorni di passi", "description": "Scrivi in C un programma che carica in un vettore i passi di 7 giorni, con funzioni per media, giorni sopra la media e giorno record, e una procedura che disegna un grafico a barre di asterischi. In un commento riporta i tuoi dati e una breve riflessione. Consegna il file passi-cognome.c.", "due_date": null, "planned_due": "2027-03-19", "topic": "Gli array monodimensionali o vettori", "pdf_url": "contenuti/compiti/vettori-c.pdf"}, {"class_id": "1e", "title": "La stazione meteo guasta", "description": "Analizza in C le temperature di 15 giorni: conta gli errori del sensore (-99), riparali con il valore del giorno prima, calcola media e giorni caldi e cerca il primo giorno con una temperatura data. Rispondi in un commento sul caso peggiore della ricerca. Consegna il file meteo-cognome.c.", "due_date": null, "planned_due": "2027-03-23", "topic": "La ricerca in un vettore", "pdf_url": "contenuti/compiti/ricerca-vettore.pdf"}, {"class_id": "1e", "title": "La gara degli algoritmi", "description": "Metti in un vettore le durate in secondi di 10 canzoni e ordinale con selezione e inserzione, stampandole in minuti:secondi e contando i confronti. Ripeti la gara su playlist già ordinata e al contrario e riporta i sei risultati in un commento, spiegando chi vince. Consegna il file playlist-cognome.c.", "due_date": null, "planned_due": "2027-04-01", "topic": "L'ordinamento degli elementi di un vettore", "pdf_url": "contenuti/compiti/ordinamento-vettore.pdf"}, {"class_id": "1e", "title": "La cassa della pizzata di classe", "description": "Scrivi un programma Python che chiede persone, pizze e bibite, calcola il totale con un accumulatore e la quota a testa, e con // e % dice quanti tavoli da 6 sono pieni. In fondo aggiungi un commento con l'output dell'esempio. Consegna il file pizzata-cognome.py.", "due_date": null, "planned_due": "2027-04-06", "topic": "Introduzione a Python", "pdf_url": "contenuti/compiti/python-intro.pdf"}, {"class_id": "1e", "title": "La biglietteria del parco divertimenti", "description": "Scrivi un programma che legge età, altezza e giorno e applica le regole del parco: prezzo con una selezione doppia, supplemento del weekend con or e accesso alle montagne russe con and. Prova i 4 casi della scheda e scrivi l'esito in un commento. Consegna il file parco-cognome.py.", "due_date": null, "planned_due": "2027-04-08", "topic": "Python: la selezione semplice e doppia", "pdf_url": "contenuti/compiti/python-selezione.pdf"}, {"class_id": "1e", "title": "La sfida delle tabelline", "description": "Programma un gioco in cui il computer fa domande casuali sulle tabelline finché il giocatore ha vite: controlla con un while il numero di vite scelto e conta i punti. Fai giocare 3 persone e scrivi i loro punteggi in un commento. Consegna il file tabelline-cognome.py.", "due_date": null, "planned_due": "2027-04-13", "topic": "Python: l'iterazione indefinita (while)", "pdf_url": "contenuti/compiti/python-while.pdf"}, {"class_id": "1e", "title": "La fabbrica delle figure", "description": "Con cicli for annidati stampa con i caratteri un quadrato, un triangolo e una scacchiera di lato scelto dall'utente, poi inventa una quarta figura e spiega in un commento come funziona. Consegna il file figure-cognome.py.", "due_date": null, "planned_due": "2027-04-16", "topic": "Python: l'iterazione definita (for)", "pdf_url": "contenuti/compiti/python-for.pdf"}, {"class_id": "1e", "title": "Il carrello della spesa online", "description": "Costruisci un carrello online con le funzioni prezzo_scontato, spedizione e leggi_numero e un main che legge gli articoli con un ciclo for e stampa subtotale, spedizione e totale, usando il punto di ingresso. Solo main può stampare. Consegna il file carrello-cognome.py.", "due_date": null, "planned_due": "2027-04-20", "topic": "Python: le funzioni", "pdf_url": "contenuti/compiti/python-funzioni.pdf"}, {"class_id": "1e", "title": "La mia classifica dei film", "description": "Con due liste parallele riempite da un while con valore sentinella, raccogli almeno 6 titoli con il loro voto, stampa la classifica, il preferito e la media. Copia l'output in un commento in fondo al file. Consegna il file classifica-cognome.py.", "due_date": null, "planned_due": "2027-04-23", "topic": "Python: le liste", "pdf_url": "contenuti/compiti/python-liste.pdf"}, {"class_id": "1e", "title": "Caccia ai segnali di casa", "description": "Trova in casa almeno 8 dispositivi che comunicano e, in una tabella di Calc, indica mezzo trasmissivo, tipo di segnale e possibili disturbi. Misura la velocità della linea con fast.com e calcola con le formule i tempi di download di tre file. Consegna il file segnali-casa-cognome.ods.", "due_date": null, "planned_due": "2027-04-27", "topic": "Introduzione alle telecomunicazioni", "pdf_url": "contenuti/compiti/telecomunicazioni.pdf"}, {"class_id": "1e", "title": "La mappa della rete di casa", "description": "Elenca almeno 6 dispositivi di casa collegati in rete e disegna la mappa della tua LAN con LibreOffice Draw, distinguendo cavo e Wi-Fi. Indica tipo di rete e topologia e spiega che cosa funziona ancora se cade internet. Consegna il file rete-casa-cognome.pdf.", "due_date": null, "planned_due": "2027-04-30", "topic": "Che cosa sono le reti", "pdf_url": "contenuti/compiti/reti.pdf"}, {"class_id": "1e", "title": "Il piano di indirizzamento", "description": "Dividi la rete 192.168.50.0/24 in 4 sottoreti uguali per quattro ambienti della scuola. In Calc compila la tabella con indirizzo di rete, primo e ultimo host, broadcast e subnet mask, e rispondi alle domande sui dispositivi. Consegna il file piano-ip-cognome.ods.", "due_date": null, "planned_due": "2027-05-05", "topic": "Come si usano le reti", "pdf_url": "contenuti/compiti/indirizzi-ip.pdf"}, {"class_id": "1e", "title": "Il mio piano di sicurezza", "description": "Scegli 6 minacce per la tua vita digitale e valutale in Calc con probabilità, impatto, rischio e livello calcolati con le formule, poi proponi una contromisura per ognuna. In un secondo foglio scrivi 5 regole di sicurezza per un familiare. Consegna il file sicurezza-cognome.ods.", "due_date": null, "planned_due": "2027-05-07", "topic": "La sicurezza nelle reti", "pdf_url": "contenuti/compiti/sicurezza-reti.pdf"}, {"class_id": "1e", "title": "Agente segreto per un giorno", "description": "Cifra con CyberChef un messaggio di almeno 25 parole usando il metodo di Cesare, poi conta in Calc le frequenze delle lettere e prova a scoprire la chiave come un crittoanalista. Rispondi a due domande su Bellaso e sulla chiave pubblica. Consegna il file agente-segreto-cognome.ods.", "due_date": null, "planned_due": "2027-05-12", "topic": "Principi di crittografia", "pdf_url": "contenuti/compiti/crittografia.pdf"}, {"class_id": "1e", "title": "Il controllo di sicurezza dei miei account", "description": "Ispeziona 4 tuoi account (fattori usati, verifica in due passaggi, riuso) senza scrivere password, crea una passphrase di prova con i dadi e calcola quante combinazioni ha rispetto al metodo vero. Chiudi con 5 regole di sicurezza per la tua famiglia. Consegna il file account-cognome.odt.", "due_date": null, "planned_due": "2027-05-17", "topic": "L'autenticazione dell'utente", "pdf_url": "contenuti/compiti/autenticazione.pdf"}, {"class_id": "1e", "title": "Il patto firmato", "description": "Scrivi un patto digitale con la tua famiglia, calcolane l'impronta SHA-256 e firmalo in Calc con le chiavi giocattolo della lezione, poi verifica che cosa succede se il testo cambia. Ispeziona i certificati di 3 siti e intervista un adulto su SPID, PEC e firma digitale. Consegna il file patto-firmato-cognome.ods.", "due_date": null, "planned_due": "2027-05-19", "topic": "Firma elettronica e certificati digitali", "pdf_url": "contenuti/compiti/firma-digitale.pdf"}, {"class_id": "1e", "title": "Una mostra a licenza libera", "description": "Prepara una mostra digitale di 6 slide su un tema a scelta con quattro immagini davvero utilizzabili (licenze Creative Commons o pubblico dominio), ognuna con l'attribuzione TASL, più una tua opera con la licenza che scegli tu. Consegna il file mostra-libera-cognome.odp.", "due_date": null, "planned_due": "2027-05-24", "topic": "Il diritto d'autore digitale", "pdf_url": "contenuti/compiti/diritto-autore.pdf"}, {"class_id": "1e", "title": "Il poster che fa la differenza", "description": "Crea un poster A4 per una campagna della scuola contro il cyberbullismo: uno slogan positivo, le 5 mosse da fare, tre frasi di sostegno per un compagno preso di mira e i contatti utili, con un'immagine tua o a licenza libera. Consegna il file poster-cognome.pdf.", "due_date": null, "planned_due": "2027-05-27", "topic": "I rischi della rete: cyberbullismo e grooming", "pdf_url": "contenuti/compiti/cyberbullismo.pdf"}, {"class_id": "1e", "title": "L'informativa che tutti capiscono", "description": "Con un genitore controlla i permessi di 5 app sul telefono e valuta quali servono davvero. Poi scrivi in modo chiaro l'informativa privacy di CompitiBuddy, un'app inventata, rispondendo alle 6 domande del GDPR e aggiungendo la regola per chi ha meno di 14 anni. Consegna il file privacy-cognome.odt.", "due_date": null, "planned_due": "2027-05-31", "topic": "La privacy e la protezione dei dati personali", "pdf_url": "contenuti/compiti/privacy.pdf"}, {"class_id": "1e", "title": "La mia postazione da dieci e lode", "description": "Misura il posto dove studi al computer e valuta ogni misura con le formule SE di Calc, registra per due giorni le sessioni davanti agli schermi e le pause, poi proponi tre miglioramenti concreti. Consegna il file postazione-cognome.ods.", "due_date": null, "planned_due": "2027-06-04", "topic": "La sicurezza e l'ergonomia", "pdf_url": "contenuti/compiti/ergonomia.pdf"}]);
