window.PIATTAFORMA_SEED = window.PIATTAFORMA_SEED.concat([{"class_id": "3g", "title": "I sistemi di elaborazione", "description": "Dati e informazioni, hardware, architettura di von Neumann, CPU e ciclo fetch-decode-execute, gerarchia delle memorie e periferiche, con Gestione attività, il mistero dei GB del disco e un vero programma nel Little Man Computer.", "url": "contenuti/lezioni/sistemi-di-elaborazione.html", "pdf_url": "contenuti/lezioni/sistemi-di-elaborazione.pdf"}, {"class_id": "3g", "title": "Il software", "description": "Software di base e applicativo, sistema operativo, linguaggio macchina, assembly e alto livello, compilatori e interpreti, Java con bytecode e JVM, licenze proprietarie, freeware e open source, con errori di compilazione ed esecuzione su OnlineGDB.", "url": "contenuti/lezioni/software-e-linguaggi.html", "pdf_url": "contenuti/lezioni/software-e-linguaggi.pdf"}, {"class_id": "3g", "title": "I sistemi di numerazione", "description": "Sistemi non posizionali e posizionali, la regola per qualsiasi base, conversioni da e verso la base 10, somme in binario con i riporti e trucchi per i conti a mente, con la console del browser e la calcolatrice da programmatore.", "url": "contenuti/lezioni/basi-di-numerazione.html", "pdf_url": "contenuti/lezioni/basi-di-numerazione.pdf"}, {"class_id": "3g", "title": "Ottale ed esadecimale al lavoro", "description": "Ottale ed esadecimale come scrittura corta dei bit, conversioni rapide passando dal binario, permessi dei file Unix, indirizzi di memoria, indirizzi MAC, colori con trasparenza e firme dei file, con JSLinux, ipconfig e HexEd.it.", "url": "contenuti/lezioni/ottale-ed-esadecimale.html", "pdf_url": "contenuti/lezioni/ottale-ed-esadecimale.pdf"}, {"class_id": "3g", "title": "Laboratorio: la codifica dei numeri", "description": "Laboratorio di conversioni e operazioni tra basi con la calcolatrice da programmatore, la console del browser e un convertitore scritto in Java su OnlineGDB, seguito passo passo con Java Tutor e messo alla prova con una tabella di test.", "url": "contenuti/lezioni/laboratorio-codifica-numeri.html", "pdf_url": "contenuti/lezioni/laboratorio-codifica-numeri.pdf"}, {"class_id": "3g", "title": "Numeri con il segno", "description": "Modulo e segno, complemento a 1 e complemento a 2 su 8 bit, somme e sottrazioni in binario, overflow con la calcolatrice in modalità Programmatore e con il tipo byte di Java, la storia di Ariane 5 e i limiti degli interi di oggi, dal contatore di YouTube all'AI quantizzata a 8 bit.", "url": "contenuti/lezioni/numeri-interi-relativi.html", "pdf_url": "contenuti/lezioni/numeri-interi-relativi.pdf"}, {"class_id": "3g", "title": "Numeri con la virgola", "description": "Numeri binari con la virgola, perché 0,1 è periodico in binario, virgola fissa e virgola mobile, il float IEEE 754 a 32 bit codificato a mano e con il FloatConverter, precisione ed errori di arrotondamento nella console e in Java, Infinity e NaN, il Patriot del 1991 e i formati ridotti usati dall'AI.", "url": "contenuti/lezioni/numeri-reali-virgola-mobile.html", "pdf_url": "contenuti/lezioni/numeri-reali-virgola-mobile.pdf"}, {"class_id": "3g", "title": "Il debugger e le variabili", "description": "Laboratorio in Java: variabili int, double, char e boolean, esecuzione passo passo con Java Tutor, breakpoint e step over nel debugger di OnlineGDB, divisione intera, overflow di int con il fattoriale, 0.1 + 0.2, casting e Math.round, con la falena di Grace Hopper e gli assistenti AI per il codice.", "url": "contenuti/lezioni/debugger-variabili-java.html", "pdf_url": "contenuti/lezioni/debugger-variabili-java.pdf"}, {"class_id": "3g", "title": "Dalle lettere ai numeri", "description": "Il codice ASCII e l'ordinamento per codice, le tabelle a 8 bit e il mojibake, Unicode e i code point, UTF-8 da 1 a 4 byte codificato a mano e osservato con HexEd.it, emoji con modificatori e ZWJ, la lunghezza delle stringhe nella console, i token dei modelli linguistici e gli attacchi con lettere sosia.", "url": "contenuti/lezioni/codifica-caratteri.html", "pdf_url": "contenuti/lezioni/codifica-caratteri.pdf"}, {"class_id": "3g", "title": "Le immagini raster", "description": "Pixel, risoluzione e ppi, profondità di colore, modelli RGB e CMYK, peso di un'immagine non compressa, kB e KiB, compressione RLE con e senza perdita, la prima foto digitale di Kirsch, con il contagocce e la pixel art in Photopea e il calcolatore del peso in Calc.", "url": "contenuti/lezioni/immagini-raster.html", "pdf_url": "contenuti/lezioni/immagini-raster.pdf"}, {"class_id": "3g", "title": "Laboratorio: i file immagine", "description": "JPEG, PNG, GIF e WebP a confronto: la gara della compressione con Squoosh, logo contro foto in Photopea, come lavora il JPEG, firme dei file e intestazione PNG lette con HexEd.it, little-endian, file travestiti e metadati EXIF e C2PA.", "url": "contenuti/lezioni/laboratorio-file-immagine.html", "pdf_url": "contenuti/lezioni/laboratorio-file-immagine.pdf"}, {"class_id": "3g", "title": "Le immagini vettoriali", "description": "Grafica vettoriale e raster a confronto, Sketchpad e le curve di Bézier, il formato SVG scritto a mano con rect, circle, polygon, path e text, il sistema di coordinate con la y verso il basso, accessibilità con title e desc, rasterizzazione in Photopea e SVG scritti dall'AI.", "url": "contenuti/lezioni/immagini-vettoriali.html", "pdf_url": "contenuti/lezioni/immagini-vettoriali.pdf"}, {"class_id": "3g", "title": "Le immagini in movimento", "description": "Fotogrammi e frame rate, da Muybridge allo streaming, il peso di un video non compresso, fotogrammi I, P e B, bitrate, codec e contenitori, streaming adattivo, con una GIF animata su ezgif, le proprietà di un video, i calcoli in Calc e le Statistiche per nerd di YouTube.", "url": "contenuti/lezioni/immagini-in-movimento.html", "pdf_url": "contenuti/lezioni/immagini-in-movimento.pdf"}, {"class_id": "3g", "title": "I suoni", "description": "Frequenza e ampiezza, campionamento e quantizzazione, il teorema di Nyquist-Shannon, valori reali di telefono, CD e studio, peso e bitrate di un audio, compressione senza e con perdita, MIDI, con il test dell'udito, un'onda campionata in Calc e il riconoscimento vocale con l'AI.", "url": "contenuti/lezioni/suono-digitale.html", "pdf_url": "contenuti/lezioni/suono-digitale.pdf"}, {"class_id": "3g", "title": "Laboratorio: i file audio", "description": "Registrare, tagliare, sfumare e normalizzare la voce con AudioMass, il clipping, gli effetti come calcoli sui campioni, WAV contro MP3, l'intestazione WAV letta con HexEd.it, la sfida del messaggio al contrario, consenso e soppressione del rumore con l'AI.", "url": "contenuti/lezioni/laboratorio-file-audio.html", "pdf_url": "contenuti/lezioni/laboratorio-file-audio.pdf"}, {"class_id": "3g", "title": "Intelligenza artificiale e computer vision", "description": "Immagini come numeri, i compiti della computer vision, la convoluzione per trovare i bordi in Calc, reti neurali e addestramento, Fei-Fei Li e ImageNet, un classificatore con Teachable Machine, test set e matrice di confusione, bias nei dati, esempi avversari, GDPR e AI Act.", "url": "contenuti/lezioni/computer-vision.html", "pdf_url": "contenuti/lezioni/computer-vision.pdf"}, {"class_id": "3g", "title": "Ingegneria del software", "description": "Perché programmare non basta: la crisi del software e la conferenza NATO del 1968, bug famosi (Ariane 5, Mars Climate Orbiter, Patriot), le 8 caratteristiche di qualità ISO/IEC 25010, i tipi di manutenzione, Margaret Hamilton e l'Apollo 11, con bug da scovare in Java su OnlineGDB e la pagella di un'app in Calc.", "url": "contenuti/lezioni/ingegneria-del-software.html", "pdf_url": "contenuti/lezioni/ingegneria-del-software.pdf"}, {"class_id": "3g", "title": "Il ciclo di vita del software", "description": "Le fasi del ciclo di vita, requisiti funzionali e non funzionali scritti in modo verificabile, i modelli a cascata (e la sorpresa dell'articolo di Royce), iterativo, incrementale e a spirale, i livelli di test e i valori al limite, con i test Java dell'anno bisestile e il piano a incrementi in Excalidraw.", "url": "contenuti/lezioni/modelli-ciclo-di-vita.html", "pdf_url": "contenuti/lezioni/modelli-ciclo-di-vita.pdf"}, {"class_id": "3g", "title": "Agile, Scrum e Kanban", "description": "Il Manifesto agile del 2001 e i suoi valori, Scrum con ruoli, eventi e artefatti, le user story con i criteri di accettazione, Kanban e i limiti WIP, il burndown chart, con il backlog dell'app della gita, una user story in Java, una sfida a squadre con i post-it e un burndown in Calc.", "url": "contenuti/lezioni/agile-scrum-kanban.html", "pdf_url": "contenuti/lezioni/agile-scrum-kanban.pdf"}, {"class_id": "3g", "title": "La gestione dei progetti", "description": "Progetto e vincoli, la WBS, attività, durate e dipendenze, il diagramma di Gantt, il percorso critico e lo scorrimento, la legge di Brooks e i canali di comunicazione, il registro dei rischi, con la WBS in Excalidraw e Gantt e rischi in Calc o Google Fogli.", "url": "contenuti/lezioni/gestione-progetti-gantt.html", "pdf_url": "contenuti/lezioni/gestione-progetti-gantt.pdf"}, {"class_id": "3g", "title": "Il World Wide Web", "description": "Internet e web, la proposta di Tim Berners-Lee al CERN nel 1989, client e server, DNS, le parti di un URL, richieste e risposte HTTP con i codici di stato, la scheda Network dei DevTools e come funzionano i motori di ricerca.", "url": "contenuti/lezioni/world-wide-web.html", "pdf_url": "contenuti/lezioni/world-wide-web.pdf"}, {"class_id": "3g", "title": "Gli elementi base di HTML", "description": "Tag, elementi e attributi, lo scheletro di una pagina, titoli, paragrafi, formattazione del testo ed entità, annidamento corretto, con la prima pagina scritta nel Blocco note, CodePen e il validatore W3C.", "url": "contenuti/lezioni/html-elementi-base.html", "pdf_url": "contenuti/lezioni/html-elementi-base.pdf"}, {"class_id": "3g", "title": "Link, immagini, elenchi e tabelle", "description": "Link assoluti, relativi e interni, percorsi con ../, immagini con un buon testo alternativo, elenchi puntati, numerati e annidati, tabelle con caption, th, colspan e rowspan, fino all'orario della 3E in HTML.", "url": "contenuti/lezioni/html-link-immagini-tabelle.html", "pdf_url": "contenuti/lezioni/html-link-immagini-tabelle.pdf"}, {"class_id": "3g", "title": "Lo stile della pagina web: i CSS", "description": "Contenuto e presentazione, la proposta di Håkon Wium Lie, sintassi delle regole, CSS in linea, interni ed esterni, colori in esadecimale e rgb(), proprietà per testo, font, bordi, elenchi e tabelle, con CodePen, DevTools e il validatore CSS.", "url": "contenuti/lezioni/css-primi-stili.html", "pdf_url": "contenuti/lezioni/css-primi-stili.pdf"}, {"class_id": "3g", "title": "La mia prima pagina web", "description": "Laboratorio: una pagina personale scritta a mano con Blocco note, dallo scheletro con DOCTYPE e charset a elenchi, link, immagini e tabelle, fino al foglio di stile esterno, con gli errori tipici di estensioni, percorsi e maiuscole.", "url": "contenuti/lezioni/laboratorio-prima-pagina-web.html", "pdf_url": "contenuti/lezioni/laboratorio-prima-pagina-web.pdf"}, {"class_id": "3g", "title": "Classi, id e selettori CSS", "description": "Selettori di classe e di id, discendenti, figli, di gruppo e di attributo, pseudo-classi come :hover, :nth-child e :has(), la cascata con importanza, specificità e ordine, l'ereditarietà e il calcolo della specificità a mano, con una sfida su CodePen.", "url": "contenuti/lezioni/css-classi-id-specificita.html", "pdf_url": "contenuti/lezioni/css-classi-id-specificita.pdf"}, {"class_id": "3g", "title": "Il box model e i layout CSS", "description": "Contenuto, padding, bordo e margine, i conti delle dimensioni con content-box e border-box, il collasso dei margini, display block, inline, inline-block e none, la colonna centrata con margin auto e il layout a due colonne con float, misurati con i DevTools.", "url": "contenuti/lezioni/css-box-model-layout.html", "pdf_url": "contenuti/lezioni/css-box-model-layout.pdf"}, {"class_id": "3g", "title": "Un piccolo sito con layout", "description": "Laboratorio in coppia: dal wireframe su carta o Excalidraw a un sito di tre pagine con intestazione, menu orizzontale con voce attiva, due colonne, piè di pagina e un solo foglio di stile, con link relativi, debug guidato e collaudo incrociato.", "url": "contenuti/lezioni/laboratorio-layout-sito.html", "pdf_url": "contenuti/lezioni/laboratorio-layout-sito.pdf"}, {"class_id": "3g", "title": "Gli strumenti dello sviluppatore web", "description": "Lezione online: editor di testo e VS Code con Emmet, CodePen e JSFiddle senza account, i pannelli dei DevTools (Stili, Calcolato, Rete, modalità dispositivo), i validatori HTML e CSS del W3C e un uso critico degli assistenti AI, con la revisione di codice generato.", "url": "contenuti/lezioni/strumenti-sviluppo-web.html", "pdf_url": "contenuti/lezioni/strumenti-sviluppo-web.pdf"}, {"class_id": "3g", "title": "HTML semantico e accessibilità", "description": "I tag semantici di HTML5 (header, nav, main, article, section, aside, footer), la gerarchia dei titoli, pulsanti ed etichette veri, il testo alternativo informativo, decorativo e funzionale, le WCAG e la frase di Tim Berners-Lee sul web per tutti, con prove al validatore W3C, a WAVE, alla tastiera e al Narratore di Windows.", "url": "contenuti/lezioni/html-semantico-accessibilita.html", "pdf_url": "contenuti/lezioni/html-semantico-accessibilita.pdf"}, {"class_id": "3g", "title": "Il posizionamento degli elementi", "description": "Il flusso normale e i cinque valori di position (static, relative, absolute, fixed, sticky), il primo antenato posizionato, la coppia padre relative e figlio absolute, header sticky e pulsanti fixed, z-index e contesto di impilamento, con laboratori su CodePen e DevTools.", "url": "contenuti/lezioni/posizionamento-css.html", "pdf_url": "contenuti/lezioni/posizionamento-css.pdf"}, {"class_id": "3g", "title": "Il layout CSS Flexbox", "description": "Contenitore ed elementi flex, asse principale e trasversale, flex-direction, justify-content, align-items, flex-wrap e gap, il calcolo a mano di flex-grow, Flexbox Froggy, l'ispettore Flexbox di DevTools e Flexbox nelle app per telefono.", "url": "contenuti/lezioni/css-flexbox.html", "pdf_url": "contenuti/lezioni/css-flexbox.pdf"}, {"class_id": "3g", "title": "Il layout CSS Grid", "description": "Righe, colonne, gap e l'unità fr con il calcolo a mano delle larghezze, linee e span, grid-template-areas con i tag semantici, Grid Garden, un calendario di novembre 2026 costruito in Grid, subgrid e la storia della griglia da Müller-Brockmann ai browser.", "url": "contenuti/lezioni/css-grid.html", "pdf_url": "contenuti/lezioni/css-grid.pdf"}, {"class_id": "3g", "title": "Progettare un sito responsive", "description": "I tre ingredienti del responsive di Ethan Marcotte, il meta viewport e i 980 pixel finti, pixel CSS e devicePixelRatio con i calcoli, la strategia mobile first, le media query e il loro ordine, immagini fluide e srcset, tema scuro, con la modalità dispositivo dei DevTools.", "url": "contenuti/lezioni/responsive-mobile-first.html", "pdf_url": "contenuti/lezioni/responsive-mobile-first.pdf"}, {"class_id": "3g", "title": "Laboratorio: CineTerza responsive", "description": "Il sito del cineforum di classe costruito passo passo: wireframe in tre misure, HTML semantico, Flexbox per intestazione e locandine, grid-template-areas per la pagina, galleria su 1, 2 e 3 colonne, il calcolo di fr, il collaudo con DevTools, tastiera e validatori W3C.", "url": "contenuti/lezioni/sito-responsive-flexbox-grid.html", "pdf_url": "contenuti/lezioni/sito-responsive-flexbox-grid.pdf"}, {"class_id": "3g", "title": "Audio, video e contenuti incorporati", "description": "Dal plugin Flash a HTML5: i tag audio e video con più sorgenti, la regola dell'autoplay muto, sottotitoli WebVTT con track scritti in CodePen, sottotitoli, trascrizione e audiodescrizione, iframe di YouTube e OpenStreetMap con title e lazy loading, la privacy degli embed e i sottotitoli automatici con l'AI.", "url": "contenuti/lezioni/multimedia-embedded.html", "pdf_url": "contenuti/lezioni/multimedia-embedded.pdf"}, {"class_id": "3g", "title": "Responsive senza media query", "description": "Il layout intrinseco: unità fluide, min(), max() e clamp() con i calcoli, flex-wrap con flex-basis, la griglia repeat(auto-fit, minmax()) e la differenza con auto-fill, le container query, la storia delle tecniche di impaginazione e quando le media query servono ancora.", "url": "contenuti/lezioni/responsive-senza-media-query.html", "pdf_url": "contenuti/lezioni/responsive-senza-media-query.pdf"}, {"class_id": "3g", "title": "Il ruolo del sistema operativo", "description": "Che cos'è il sistema operativo, macchina estesa e gestore di risorse, le risorse che governa e l'astrazione, dall'operatore degli anni '50 alla NPU di oggi, con Gestione attività, Monitoraggio risorse e i cluster del file system.", "url": "contenuti/lezioni/ruolo-sistema-operativo.html", "pdf_url": "contenuti/lezioni/ruolo-sistema-operativo.pdf"}, {"class_id": "3g", "title": "Kernel e shell", "description": "Kernel monolitici, microkernel e ibridi, la shell grafica e a riga di comando, le chiamate di sistema e le pipe, con i primi comandi in cmd, PowerShell e in un Linux vero dentro il browser.", "url": "contenuti/lezioni/kernel-e-shell.html", "pdf_url": "contenuti/lezioni/kernel-e-shell.pdf"}, {"class_id": "3g", "title": "User mode e kernel mode", "description": "Perché serve la protezione, le due modalità della CPU, i ring di x86, il passaggio con le chiamate di sistema, la memoria divisa in esadecimale e i due tipi di crash, da Multics e Dijkstra alle schermate blu del 2024, con Gestione attività, PowerShell e Monitoraggio affidabilità.", "url": "contenuti/lezioni/user-mode-kernel-mode.html", "pdf_url": "contenuti/lezioni/user-mode-kernel-mode.pdf"}, {"class_id": "3g", "title": "Tipologie di sistemi operativi", "description": "Sistemi batch, multiprogrammati, time sharing, real time hard e soft, distribuiti, mobili ed embedded, con il calcolo dell'utilizzo della CPU, l'allarme 1202 dell'Apollo 11 e una prova dei tempi di reazione.", "url": "contenuti/lezioni/tipologie-sistemi-operativi.html", "pdf_url": "contenuti/lezioni/tipologie-sistemi-operativi.pdf"}, {"class_id": "3g", "title": "I sistemi operativi in commercio", "description": "La storia di Unix, l'annuncio di Linux del 1991, le famiglie di Windows, macOS, Linux, Android, iOS e ChromeOS, licenze proprietarie e libere, con JSLinux, la build di Windows e un censimento dei sistemi della classe.", "url": "contenuti/lezioni/sistemi-operativi-commercio.html", "pdf_url": "contenuti/lezioni/sistemi-operativi-commercio.pdf"}, {"class_id": "3g", "title": "Le prestazioni del sistema operativo", "description": "Utilizzo della CPU, throughput, tempi di completamento, di attesa e di risposta calcolati a mano, il collo di bottiglia, Gestione attività, Monitoraggio risorse e un core sotto sforzo, uptime, top e free in JSLinux, fino ai token al secondo dei chatbot.", "url": "contenuti/lezioni/prestazioni-sistema-operativo.html", "pdf_url": "contenuti/lezioni/prestazioni-sistema-operativo.pdf"}, {"class_id": "3g", "title": "La gestione della CPU: i processi", "description": "Programma e processo, il modello a cinque stati, il PCB, il cambio di contesto e i thread, con tasklist e taskkill in Windows, ps, top e /proc in JSLinux per vedere gli stati R, S e T, e i processi del browser.", "url": "contenuti/lezioni/processi-stati-pcb.html", "pdf_url": "contenuti/lezioni/processi-stati-pcb.pdf"}, {"class_id": "3g", "title": "Gli algoritmi di scheduling dei processi", "description": "FCFS, SJF, priorità e Round Robin con diagrammi di Gantt e calcolo dei tempi di attesa, completamento e risposta, l'effetto convoglio, la starvation e l'aging, un foglio Calc per l'FCFS con tempi di arrivo, il Gantt a celle colorate e il gioco a squadre in cui la classe fa la CPU.", "url": "contenuti/lezioni/scheduling-processi.html", "pdf_url": "contenuti/lezioni/scheduling-processi.pdf"}, {"class_id": "3g", "title": "La gestione degli interrupt", "description": "Polling e interrupt a confronto con i conti, interrupt hardware, eccezioni e chiamate di sistema, i sei passi della gestione e il vettore delle interruzioni, il timer che rende possibile il Round Robin, priorità e l'allarme 1202 di Apollo 11, con /proc/interrupts in JSLinux, gli IRQ di Windows e gli eventi del browser.", "url": "contenuti/lezioni/gestione-interrupt.html", "pdf_url": "contenuti/lezioni/gestione-interrupt.pdf"}, {"class_id": "3g", "title": "La memoria fisica e virtuale", "description": "Gerarchia delle memorie con tempi di accesso reali, indirizzi fisici e potenze di 2, indirizzi logici e traduzione con registro base e limite, l'idea di memoria virtuale con il file di paging, fino alla RAM che serve ai modelli di intelligenza artificiale.", "url": "contenuti/lezioni/memoria-fisica-virtuale.html", "pdf_url": "contenuti/lezioni/memoria-fisica-virtuale.pdf"}, {"class_id": "3g", "title": "L'allocazione contigua a partizioni", "description": "Partizioni fisse e variabili, frammentazione interna ed esterna, first fit, best fit e worst fit svolti a mano e in un torneo a squadre, compattazione, simulazione in Calc e in Java.", "url": "contenuti/lezioni/allocazione-partizioni.html", "pdf_url": "contenuti/lezioni/allocazione-partizioni.pdf"}, {"class_id": "3g", "title": "L'allocazione non contigua a paginazione statica", "description": "Pagine e frame, tabella delle pagine, traduzione degli indirizzi in decimale e in esadecimale, operazioni sui bit nella console del browser, dimensione delle tabelle e TLB, frammentazione interna, un traduttore in Java e le pagine nei server dei chatbot.", "url": "contenuti/lezioni/paginazione-statica.html", "pdf_url": "contenuti/lezioni/paginazione-statica.pdf"}, {"class_id": "3g", "title": "La memoria virtuale a paginazione dinamica", "description": "Paginazione su richiesta e bit di validità, i passi di un page fault, tabelle FIFO, LRU e OPT svolte a mano e in Calc, l'anomalia di Belady scoperta con un programma Java, thrashing e working set, la memoria virtuale di Atlas e dei modelli di AI sul PC.", "url": "contenuti/lezioni/paginazione-dinamica.html", "pdf_url": "contenuti/lezioni/paginazione-dinamica.pdf"}, {"class_id": "3g", "title": "La memoria virtuale a segmentazione", "description": "Segmenti di codice, dati, stack e heap, tabella dei segmenti con base, limite e permessi, segmentation fault, i segmenti di un processo Linux e il controllo dei limiti in Java, confronto con la paginazione e segmentazione paginata, fino alla sicurezza della memoria di oggi.", "url": "contenuti/lezioni/segmentazione-memoria.html", "pdf_url": "contenuti/lezioni/segmentazione-memoria.pdf"}, {"class_id": "3g", "title": "Il file system", "description": "File, cartelle e metadati, percorsi assoluti e relativi in Windows e Linux, permessi rwx e chmod in ottale, FAT32, exFAT, NTFS ed ext4 a confronto, da Unix nel 1974 alle app di Android, con Esplora file e un Linux vero nel browser.", "url": "contenuti/lezioni/file-system-permessi.html", "pdf_url": "contenuti/lezioni/file-system-permessi.pdf"}, {"class_id": "3g", "title": "Dove finiscono i byte sul disco", "description": "Blocchi e cluster, frammentazione interna ed esterna, allocazione contigua, concatenata e indicizzata, la FAT e l'i-node con il calcolo dei puntatori, fino a SSD, TRIM ed extent, con Calc, JSLinux e le dimensioni su disco di Windows.", "url": "contenuti/lezioni/allocazione-spazio-disco.html", "pdf_url": "contenuti/lezioni/allocazione-spazio-disco.pdf"}, {"class_id": "3g", "title": "La gestione delle periferiche", "description": "Periferiche a blocchi e a caratteri, controller, driver e firmware, polling, interrupt e DMA con un calcolo, buffering, rimozione sicura e spooling, dall'Apollo 11 alle NPU, con Gestione dispositivi, la coda di stampa e /dev in Linux.", "url": "contenuti/lezioni/gestione-periferiche.html", "pdf_url": "contenuti/lezioni/gestione-periferiche.pdf"}, {"class_id": "3g", "title": "Proteggere i dati", "description": "Protezione e sicurezza, riservatezza, integrità e disponibilità, utenti, permessi e minimo privilegio, autenticazione a due fattori e forza delle password con un calcolo, backup 3-2-1 verificato con l'hash, malware, WannaCry, etica e legge, fino a phishing con l'AI e passkey.", "url": "contenuti/lezioni/protezione-sicurezza-dati.html", "pdf_url": "contenuti/lezioni/protezione-sicurezza-dati.pdf"}, {"class_id": "3g", "title": "DomoDash: il cruscotto della casa intelligente", "description": "Progetto di gruppo in sei settimane: scenario, ruoli e Kanban, schizzo e wireframe in Excalidraw, sensori e attuatori come card in HTML e CSS Grid, dati in JSON trasformati in pagina con un piccolo script, test di accessibilità e presentazione finale con griglia di valutazione.", "url": "contenuti/lezioni/progetto-casa-intelligente.html", "pdf_url": "contenuti/lezioni/progetto-casa-intelligente.pdf"}, {"class_id": "3g", "title": "Il nostro Comune a raggi X", "description": "Progetto di gruppo in sei settimane: rifiuti ed energia del proprio Comune con dati aperti veri di ISPRA, GSE e Terna citati con fonte e licenza, wireframe mobile first, grafici accessibili da Calc, layout responsive con Flexbox, Grid e media query, collaudo e presentazione con griglia di valutazione.", "url": "contenuti/lezioni/progetto-sito-ambiente.html", "pdf_url": "contenuti/lezioni/progetto-sito-ambiente.pdf"}, {"class_id": "3g", "title": "La seconda vita dei rifiuti elettronici", "description": "Che cos'è un RAEE, materie preziose e sostanze pericolose, i numeri veri del mondo e dell'Italia calcolati in Calc, i gruppi R1-R5, centro di raccolta, uno contro uno e uno contro zero, economia circolare, diritto alla riparazione e come cancellare i dati prima di dare via un telefono.", "url": "contenuti/lezioni/raee-rifiuti-elettronici.html", "pdf_url": "contenuti/lezioni/raee-rifiuti-elettronici.pdf"}, {"class_id": "3g", "title": "Copiare, citare, creare", "description": "La legge italiana sul diritto d'autore, l'articolo 70 per la scuola, le licenze Creative Commons e i siti con licenza propria, i diritti sulle registrazioni musicali, le licenze del software, l'AI nella legge 132/2025 e nell'AI Act, con crediti scritti in HTML, ricerca inversa delle immagini e una licenza per la propria opera.", "url": "contenuti/lezioni/diritto-autore-in-rete.html", "pdf_url": "contenuti/lezioni/diritto-autore-in-rete.pdf"}, {"class_id": "3g", "title": "Sicuri al lavoro, a partire dal laboratorio", "description": "Il D.Lgs. 81/2008 e la Costituzione, lo studente equiparato al lavoratore, le figure della sicurezza a scuola, la matrice dei rischi R = P × D in Calc, rischio elettrico e potenza delle ciabatte, estintori, cartelli ed evacuazione, i diritti al videoterminale e la sicurezza in PCTO.", "url": "contenuti/lezioni/sicurezza-lavoro-laboratorio.html", "pdf_url": "contenuti/lezioni/sicurezza-lavoro-laboratorio.pdf"}]);
